package com.example.placement;

import android.app.AlertDialog;
import android.content.ActivityNotFoundException;
import android.content.Intent;
import android.graphics.Color;
import android.net.Uri;
import android.os.Build;
import android.provider.MediaStore;
import android.database.Cursor;
import android.provider.OpenableColumns;
import android.text.InputType;
import android.view.View;
import android.widget.*;
import java.net.URI;
import java.util.*;

/** Local-only profile editor screens. Backend repositories can replace DemoSession later. */
public abstract class ProfileFeatureActivity extends BaseActivity {
    static final int PICK_PHOTO=4101, PICK_DOCUMENT=4102, PICK_CERTIFICATE=4103, PICK_ACHIEVEMENT=4104;
    String pendingKey=""; Certification pendingCertification; Achievement pendingAchievement;

    @Override protected int layout(){String n=getClass().getSimpleName().replace("Activity","").replaceAll("([a-z])([A-Z])","$1_$2").toLowerCase();return getResources().getIdentifier("activity_"+n,"layout",getPackageName());}
    @Override protected void render(){switch(getClass().getSimpleName()){
        case "PersonalInformationActivity":personal();break;case "AcademicInformationActivity":academic();break;case "DocumentsActivity":documents();break;
        case "ProjectsActivity":projects();break;case "CertificationsActivity":certifications();break;case "CodingProfilesActivity":codingProfiles();break;
        case "SkillsActivity":skills();break;case "AchievementsActivity":achievements();break;case "ProfessionalLinksActivity":professionalLinks();break;case "WorkExperienceActivity":workExperience();break;case "ProfilePreviewActivity":preview();break;
    }}

    @Override protected LinearLayout page(String title){toolbar(title);scroll(false);return body;}
    String value(String key,String fallback){return DemoSession.profile.getOrDefault(key,fallback);}
    void save(String key,String v){DemoSession.profile.put(key,v==null?"":v.trim());}
    void actionRow(LinearLayout box,String label,Runnable work){Button b=button(label,false,work);box.addView(b,lp(-1,44));}
    void saveButton(LinearLayout l,String label,Runnable work){action(l,label,work);}
    void editPrompt(String label,String key,String current,int inputType,boolean required,java.util.function.Consumer<String> commit){EditText field=input(label,inputType);field.setText(current);new AlertDialog.Builder(this).setTitle(label).setView(field).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String v=field.getText().toString().trim();if(required&&v.isEmpty()){toast(label+" is required");return;}commit.accept(v);recreate();}).show();}
    void textFieldDialog(String title,String hint,int type,java.util.function.Consumer<EditText> done){EditText e=input(hint,type);LinearLayout wrap=column();pad(wrap,8);wrap.addView(e,lp(-1,52));new AlertDialog.Builder(this).setTitle(title).setView(wrap).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->done.accept(e)).show();}
    boolean validWebUrl(String raw){try{Uri u=Uri.parse(raw.trim());return "https".equalsIgnoreCase(u.getScheme())&&u.getHost()!=null&&u.getHost().contains(".")&&u.getUserInfo()==null;}catch(Exception ex){return false;}}
    boolean validGithubRepo(String raw){try{Uri u=Uri.parse(raw.trim());if(!"https".equalsIgnoreCase(u.getScheme())||!"github.com".equalsIgnoreCase(u.getHost())||u.getUserInfo()!=null)return false;String[] p=u.getPathSegments().toArray(new String[0]);return p.length==2&&!p[0].isEmpty()&&!p[1].isEmpty()&&!p[0].equalsIgnoreCase("settings");}catch(Exception ex){return false;}}
    boolean domain(String raw,String host){try{Uri u=Uri.parse(raw.trim());String h=u.getHost();return validWebUrl(raw)&&h!=null&&(h.equalsIgnoreCase(host)||h.toLowerCase(Locale.ROOT).endsWith("."+host));}catch(Exception e){return false;}}
    void openUrl(String raw){if(!validWebUrl(raw)){toast("Enter a valid HTTPS URL first");return;}try{Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse(raw.trim()));if(i.resolveActivity(getPackageManager())!=null)startActivity(i);else toast("No app is available to open this link");}catch(ActivityNotFoundException e){toast("No app is available to open this link");}}
    String displayName(Uri uri){String name="Selected file";Cursor c=null;try{c=getContentResolver().query(uri,null,null,null,null);if(c!=null&&c.moveToFirst()){int i=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(i>=0)name=c.getString(i);}}catch(Exception ignored){}finally{if(c!=null)c.close();}return name;}
    void pickFile(String mime,int request,String key){pendingKey=key;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType(mime);i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,request);}catch(ActivityNotFoundException e){toast("The system file picker is unavailable");}}
    void pickPhoto(){if(Build.VERSION.SDK_INT>=33){try{startActivityForResult(new Intent(MediaStore.ACTION_PICK_IMAGES),PICK_PHOTO);return;}catch(Exception ignored){}}pickFile("image/*",PICK_PHOTO,"Profile Photograph");}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();String name=displayName(uri);String mime=getContentResolver().getType(uri);if(!validPickedType(request,pendingKey,mime,name)){toast("Choose a supported PDF or image file");return;}try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}
        if(request==PICK_PHOTO){DemoSession.profilePhotoUri=uri.toString();DemoSession.profilePhotoName=name;DemoSession.documents.put("Profile Photograph",name);DemoSession.documentUris.put("Profile Photograph",uri.toString());DemoSession.documentItems.put("Profile Photograph",new StudentDocument("Profile Photograph",name,uri));}
        else if(request==PICK_DOCUMENT){DemoSession.documents.put(pendingKey,name);DemoSession.documentUris.put(pendingKey,uri.toString());DemoSession.documentItems.put(pendingKey,new StudentDocument(pendingKey,name,uri));}
        else if(request==PICK_CERTIFICATE&&pendingCertification!=null){pendingCertification.fileName=name;pendingCertification.fileUri=uri.toString();}
        else if(request==PICK_ACHIEVEMENT&&pendingAchievement!=null){pendingAchievement.proofName=name;pendingAchievement.proofUri=uri.toString();}
        recreate();
    }

    boolean validPickedType(int request,String key,String mime,String name){String m=mime==null?"":mime.toLowerCase(Locale.ROOT),n=name==null?"":name.toLowerCase(Locale.ROOT);boolean image=m.startsWith("image/")||n.endsWith(".jpg")||n.endsWith(".jpeg")||n.endsWith(".png")||n.endsWith(".webp");boolean pdf=m.equals("application/pdf")||n.endsWith(".pdf");if(request==PICK_PHOTO)return image;if(key.equals("Resume/CV"))return pdf;if(request==PICK_DOCUMENT||request==PICK_CERTIFICATE||request==PICK_ACHIEVEMENT)return image||pdf;return false;}
    void personal(){LinearLayout l=page("Personal Information");sectionLabel(l,"STUDENT DETAILS");fieldRow(l,"Full name",DemoSession.name,()->editPrompt("Full name","name",DemoSession.name,InputType.TYPE_CLASS_TEXT,true,v->DemoSession.name=v));fieldRow(l,"SAP ID",DemoSession.sapId,()->editPrompt("SAP ID","sap",DemoSession.sapId,InputType.TYPE_CLASS_TEXT,true,v->DemoSession.sapId=v));fieldRow(l,"College email",DemoSession.email,()->editPrompt("College email","email",DemoSession.email,InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS,true,v->{if(!android.util.Patterns.EMAIL_ADDRESS.matcher(v).matches()){toast("Enter a valid email address");return;}DemoSession.email=v;}));fieldRow(l,"Phone number",value("Phone number",""),()->editPrompt("Phone number","phone",value("Phone number",""),InputType.TYPE_CLASS_PHONE,true,v->save("Phone number",v)));fieldRow(l,"Date of birth",value("Date of birth",""),()->editPrompt("Date of birth","dob",value("Date of birth",""),InputType.TYPE_CLASS_TEXT,true,v->save("Date of birth",v)));fieldRow(l,"Address",value("Address",""),()->editPrompt("Address","address",value("Address",""),InputType.TYPE_CLASS_TEXT,true,v->save("Address",v)));
        heading(l,"Profile photograph");LinearLayout photo=column();pad(photo,14);if(!DemoSession.profilePhotoUri.isEmpty()){ImageView image=new ImageView(this);image.setImageURI(Uri.parse(DemoSession.profilePhotoUri));image.setScaleType(ImageView.ScaleType.CENTER_CROP);photo.addView(image,lp(96,96));photo.addView(text(DemoSession.profilePhotoName,13,muted,false));}else photo.addView(text("No profile photograph selected",14,muted,false));actionRow(photo,"Choose photograph",this::pickPhoto);if(!DemoSession.profilePhotoUri.isEmpty())actionRow(photo,"Remove photograph",()->{DemoSession.profilePhotoUri="";DemoSession.profilePhotoName="";DemoSession.documents.remove("Profile Photograph");DemoSession.documentUris.remove("Profile Photograph");DemoSession.documentItems.remove("Profile Photograph");recreate();});card(l,photo);}
    void fieldRow(LinearLayout l,String title,String detail,Runnable edit){item(l,title,detail.isEmpty()?"Not provided":detail,"EDIT",edit);}
    void sectionLabel(LinearLayout l,String s){TextView t=text(s,11,blue,true);t.setPadding(0,dp(8),0,dp(4));l.addView(t);}

    void academic(){LinearLayout l=page("Academic Information");String[][] fields={{"Institution","SVKM's NMIMS, Hyderabad Campus"},{"Programme","B.Tech"},{"Branch",DemoSession.branch},{"Current semester","6"},{"CGPA","8.2"},{"Backlogs","0"},{"Class 10 percentage","91"},{"Class 12 percentage","88"},{"Graduation year","2027"}};for(String[] f:fields)fieldRow(l,f[0],value(f[0],f[1]),()->editPrompt(f[0],f[0],value(f[0],f[1]),InputType.TYPE_CLASS_TEXT,true,v->{if(f[0].equals("CGPA")&&!numberBetween(v,0,10)){toast("CGPA must be between 0 and 10");return;}if((f[0].contains("percentage"))&&!numberBetween(v,0,100)){toast("Enter a percentage between 0 and 100");return;}save(f[0],v);if(f[0].equals("Branch"))DemoSession.branch=v;}));note(l,"Academic values are kept in this device's demo session only.");}
    boolean numberBetween(String v,double min,double max){try{double x=Double.parseDouble(v);return x>=min&&x<=max;}catch(Exception e){return false;}}

    void documents(){LinearLayout l=page("Resume and Documents");note(l,"Files are selected locally. Cloud upload integration will be added later; nothing is uploaded in this demo.");String[] singles={"Resume/CV","Profile Photograph","Class 10 marksheet","Class 12 marksheet"};for(String key:singles)documentCard(l,key,false);heading(l,"Semester marksheets");documentGroup(l,"Semester marksheet");heading(l,"Internship certificates");documentGroup(l,"Internship certificate");heading(l,"Other certificates");documentGroup(l,"Other certificate");heading(l,"Additional documents");documentGroup(l,"Additional document");if(DemoSession.documents.isEmpty())note(l,"No documents selected yet. Select a local PDF or image to get started.");}
    void documentGroup(LinearLayout l,String category){for(String k:new ArrayList<>(DemoSession.documents.keySet()))if(k.equals(category)||k.startsWith(category+" #")||(category.equals("Additional document")&&k.startsWith("Additional: ")))documentCard(l,k,true);actionRow(l,category.equals("Additional document")?"Add Document":"Add "+category.toLowerCase(Locale.ROOT),()->{if(category.equals("Additional document")){textFieldDialog("Document name","e.g. Internship letter",InputType.TYPE_CLASS_TEXT,e->{String n=e.getText().toString().trim();if(n.isEmpty()){toast("Document name is required");return;}pickFile("*/*",PICK_DOCUMENT,"Additional: "+n);});}else{int number=1;while(DemoSession.documents.containsKey(category+" #"+number))number++;pickFile("*/*",PICK_DOCUMENT,category+" #"+number);}});}
    void documentCard(LinearLayout l,String key,boolean multiple){LinearLayout c=column();pad(c,13);c.addView(text(key,15,ink,true));String name=DemoSession.documents.get(key);c.addView(text(name==null?"Not Selected":"Selected Locally  ·  "+name,13,name==null?muted:success,false));LinearLayout actions=row();Button choose=button(name==null?"Select file":"Replace",false,()->{if(key.equals("Profile Photograph"))pickPhoto();else pickFile(mimeFor(key),PICK_DOCUMENT,key);});actions.addView(choose,new LinearLayout.LayoutParams(0,dp(42),1));if(name!=null){Button remove=button("Remove",false,()->{DemoSession.documents.remove(key);DemoSession.documentUris.remove(key);DemoSession.documentItems.remove(key);if(key.equals("Profile Photograph")){DemoSession.profilePhotoUri="";DemoSession.profilePhotoName="";}recreate();});LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,dp(42),1);rp.leftMargin=dp(6);actions.addView(remove,rp);String uri=DemoSession.documentUris.get(key);if(uri!=null){Button view=button("View",false,()->openLocal(uri));LinearLayout.LayoutParams vp=new LinearLayout.LayoutParams(0,dp(42),1);vp.leftMargin=dp(6);actions.addView(view,vp);}}c.addView(actions);card(l,c);}
    String mimeFor(String key){return key.equals("Profile Photograph")?"image/*":key.equals("Resume/CV")?"application/pdf":"*/*";}
    void openLocal(String raw){try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.parse(raw),getContentResolver().getType(Uri.parse(raw)));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(i.resolveActivity(getPackageManager())!=null)startActivity(i);else toast("No app is available to view this file");}catch(Exception e){toast("Could not open this selected file");}}

    void projects(){LinearLayout l=page("Projects");note(l,"Each project contains only its title and GitHub repository URL.");if(DemoSession.projects.isEmpty())note(l,"No projects added yet. Add a project to show your work.");for(int i=0;i<DemoSession.projects.size();i++){final int index=i;Project p=DemoSession.projects.get(i);LinearLayout c=column();pad(c,14);c.addView(text(p.title,17,ink,true));c.addView(text(p.githubUrl,13,muted,false));LinearLayout row=row();Button open=button("Open GitHub",true,()->openUrl(p.githubUrl));row.addView(open,new LinearLayout.LayoutParams(0,dp(44),1));Button edit=button("Edit",false,()->projectDialog(index));LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(0,dp(44),1);ep.leftMargin=dp(5);row.addView(edit,ep);Button del=button("Delete",false,()->confirmDelete("Delete project?",()->{DemoSession.projects.remove(index);recreate();}));LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(0,dp(44),1);dp.leftMargin=dp(5);row.addView(del,dp);c.addView(row);card(l,c);}action(l,"Add Project",()->projectDialog(-1));}
    void projectDialog(int index){Project old=index>=0?DemoSession.projects.get(index):null;LinearLayout box=column();pad(box,8);EditText title=input("Project Title",InputType.TYPE_CLASS_TEXT);EditText url=input("GitHub Repository URL",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);title.setSingleLine(true);url.setSingleLine(true);if(old!=null){title.setText(old.title);url.setText(old.githubUrl);}label(box,"Project Title");box.addView(title,lp(-1,50));label(box,"GitHub Repository URL");box.addView(url,lp(-1,50));new AlertDialog.Builder(this).setTitle(old==null?"Add Project":"Edit Project").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String t=title.getText().toString().trim(),u=url.getText().toString().trim();if(t.isEmpty()){title.setError("Project title is required");return;}if(u.isEmpty()){url.setError("GitHub URL is required");return;}if(!validGithubRepo(u)){url.setError("Enter an HTTPS github.com/owner/repository URL");return;}if(old==null)DemoSession.projects.add(new Project(t,u));else{old.title=t;old.githubUrl=u;}recreate();}).show();}
    void confirmDelete(String message,Runnable action){new AlertDialog.Builder(this).setMessage(message).setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->action.run()).show();}

    void certifications(){LinearLayout l=page("Certifications");note(l,"Any example records in this section are demo data and are not verified credentials.");if(DemoSession.certifications.isEmpty())note(l,"No certifications added yet.");for(int i=0;i<DemoSession.certifications.size();i++){final int ix=i;Certification x=DemoSession.certifications.get(i);LinearLayout c=column();pad(c,14);c.addView(text(x.name,17,ink,true));c.addView(text(x.organization+"  ·  "+x.issueDate,13,muted,false));if(!x.credentialId.isEmpty())c.addView(text("Credential ID: "+x.credentialId,12,muted,false));if(!x.fileName.isEmpty())c.addView(text("Selected locally: "+x.fileName,12,success,false));LinearLayout actions=row();actions.addView(button("Edit",false,()->certDialog(ix)),new LinearLayout.LayoutParams(0,dp(42),1));Button file=button(x.fileName.isEmpty()?"Select file":"Replace file",false,()->{pendingCertification=x;pickFile("*/*",PICK_CERTIFICATE,"cert");});LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(0,dp(42),1);fp.leftMargin=dp(5);actions.addView(file,fp);if(!x.fileUri.isEmpty()){Button viewFile=button("View file",false,()->openLocal(x.fileUri));LinearLayout.LayoutParams vf=new LinearLayout.LayoutParams(0,dp(42),1);vf.leftMargin=dp(5);actions.addView(viewFile,vf);}if(!x.verificationUrl.isEmpty()){Button open=button("Verify",true,()->openUrl(x.verificationUrl));LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(0,dp(42),1);op.leftMargin=dp(5);actions.addView(open,op);}Button del=button("Delete",false,()->confirmDelete("Delete certification?",()->{DemoSession.certifications.remove(ix);recreate();}));LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(0,dp(42),1);dp.leftMargin=dp(5);actions.addView(del,dp);c.addView(actions);card(l,c);}action(l,"Add Certification",()->certDialog(-1));}
    void certDialog(int index){Certification old=index>=0?DemoSession.certifications.get(index):null;LinearLayout box=column();pad(box,8);EditText[] f=new EditText[5];String[] labels={"Certification Name","Issuing Organization","Issue Date","Credential ID (optional)","Credential Verification URL (optional)"};String[] vals=old==null?new String[]{"","","","",""}:new String[]{old.name,old.organization,old.issueDate,old.credentialId,old.verificationUrl};for(int i=0;i<f.length;i++){label(box,labels[i]);f[i]=input(labels[i],i==4?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI:InputType.TYPE_CLASS_TEXT);f[i].setText(vals[i]);box.addView(f[i],lp(-1,48));}new AlertDialog.Builder(this).setTitle(old==null?"Add Certification":"Edit Certification").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String n=f[0].getText().toString().trim(),org=f[1].getText().toString().trim(),date=f[2].getText().toString().trim(),id=f[3].getText().toString().trim(),url=f[4].getText().toString().trim();if(n.isEmpty()||org.isEmpty()||date.isEmpty()){toast("Name, organization, and issue date are required");return;}if(!url.isEmpty()&&!validWebUrl(url)){f[4].setError("Enter a valid HTTPS URL");return;}if(old==null)DemoSession.certifications.add(new Certification(n,org,date,id,url));else{old.name=n;old.organization=org;old.issueDate=date;old.credentialId=id;old.verificationUrl=url;}recreate();}).show();}

    void codingProfiles(){LinearLayout l=page("Coding Profiles");String[] platforms={"GitHub","LeetCode","HackerRank","CodeChef","Codeforces","GeeksforGeeks"};for(String platform:platforms){CodingProfile p=DemoSession.codingProfiles.get(platform);if(p==null){p=new CodingProfile(platform);DemoSession.codingProfiles.put(platform,p);}final CodingProfile record=p;LinearLayout c=column();pad(c,14);c.addView(text(platform,17,ink,true));c.addView(text(record.username==null||record.username.isEmpty()?"Username not set":record.username,13,muted,false));c.addView(text(record.url==null||record.url.isEmpty()?"Profile URL not set":record.url,13,muted,false));String stats="";if(record.problemsSolved!=null&&!record.problemsSolved.isEmpty())stats+="Problems: "+record.problemsSolved+"  ";if(record.rating!=null&&!record.rating.isEmpty())stats+="Rating: "+record.rating+"  ";if(record.badges!=null&&!record.badges.isEmpty())stats+="Badges: "+record.badges;if(!stats.isEmpty())c.addView(text("Manual stats: "+stats,12,muted,false));LinearLayout actions=row();actions.addView(button("Edit",false,()->codingDialog(record)),new LinearLayout.LayoutParams(0,dp(42),1));if(record.url!=null&&!record.url.isEmpty()){Button open=button("Open Profile",true,()->openUrl(record.url));LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(0,dp(42),1);op.leftMargin=dp(6);actions.addView(open,op);}c.addView(actions);card(l,c);}note(l,"Statistics are manually entered by the student. No platform APIs or scraping are used.");}
    void codingDialog(CodingProfile p){LinearLayout box=column();pad(box,8);EditText user=input("Username (optional)",InputType.TYPE_CLASS_TEXT),url=input("Profile URL",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI),problems=input("Problems Solved (optional)",InputType.TYPE_CLASS_NUMBER),rating=input("Coding Rating (optional)",InputType.TYPE_CLASS_TEXT),badges=input("Badges Earned (optional)",InputType.TYPE_CLASS_TEXT);user.setText(p.username);url.setText(p.url);problems.setText(p.problemsSolved);rating.setText(p.rating);badges.setText(p.badges);for(EditText e:new EditText[]{user,url,problems,rating,badges})box.addView(e,lp(-1,48));new AlertDialog.Builder(this).setTitle(p.platform+" Profile").setView(box).setNegativeButton("Cancel",null).setNeutralButton("Clear",(d,w)->{p.username="";p.url="";p.problemsSolved="";p.rating="";p.badges="";recreate();}).setPositiveButton("Save",(d,w)->{String u=url.getText().toString().trim();if(!u.isEmpty()&&!validPlatformUrl(p.platform,u)){url.setError("Use a valid HTTPS "+p.platform+" profile URL");return;}p.username=user.getText().toString().trim();p.url=u;p.problemsSolved=problems.getText().toString().trim();p.rating=rating.getText().toString().trim();p.badges=badges.getText().toString().trim();recreate();}).show();}
    boolean validPlatformUrl(String p,String raw){String host="";switch(p){case "GitHub":host="github.com";break;case "LeetCode":host="leetcode.com";break;case "HackerRank":host="hackerrank.com";break;case "CodeChef":host="codechef.com";break;case "Codeforces":host="codeforces.com";break;default:host="geeksforgeeks.org";}return domain(raw,host);}

    void skills(){LinearLayout l=page("Skills");String[] cats={"Programming Languages","Web Development","Databases","Frameworks","Tools and Technologies","Other Skills"};for(String cat:cats){heading(l,cat);LinkedHashSet<String> existing=DemoSession.skills.get(cat);if(existing==null){existing=new LinkedHashSet<>();DemoSession.skills.put(cat,existing);}final LinkedHashSet<String> set=existing;if(set.isEmpty())l.addView(text("No skills added",13,muted,false));for(String skill:new ArrayList<>(set)){LinearLayout chip=row();TextView t=text(skill,13,ink,true);t.setPadding(dp(12),dp(8),dp(12),dp(8));t.setBackground(shape(Color.WHITE,18,line));chip.addView(t);TextView remove=text("×",18,blue,true);remove.setPadding(dp(10),dp(4),dp(10),dp(4));chip.addView(remove);remove.setOnClickListener(v->{set.remove(skill);recreate();});l.addView(chip,lp(-2,-2));}actionRow(l,"Add skill to "+cat,()->skillDialog(cat));}}
    void skillDialog(String category){textFieldDialog("Add skill · "+category,"Skill name",InputType.TYPE_CLASS_TEXT,e->{String name=e.getText().toString().trim();if(name.isEmpty()){toast("Skill name is required");return;}LinkedHashSet<String> set=DemoSession.skills.computeIfAbsent(category,k->new LinkedHashSet<>());for(String old:set)if(old.equalsIgnoreCase(name)){toast("That skill is already listed");return;}set.add(name);recreate();});}

    void achievements(){LinearLayout l=page("Achievements");note(l,"Achievement records are local demo entries and are not independently verified.");if(DemoSession.achievements.isEmpty())note(l,"No achievements added yet.");for(int i=0;i<DemoSession.achievements.size();i++){final int ix=i;Achievement a=DemoSession.achievements.get(i);LinearLayout c=column();pad(c,14);c.addView(text(a.title,17,ink,true));c.addView(text(a.description,14,muted,false));c.addView(text(a.organization+"  ·  "+a.date,12,muted,false));if(!a.proofName.isEmpty())c.addView(text("Proof selected locally: "+a.proofName,12,success,false));LinearLayout actions=row();actions.addView(button("Edit",false,()->achievementDialog(ix)),new LinearLayout.LayoutParams(0,dp(42),1));Button proof=button(a.proofName.isEmpty()?"Select proof":"Replace proof",false,()->{pendingAchievement=a;pickFile("*/*",PICK_ACHIEVEMENT,"proof");});LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(0,dp(42),1);pp.leftMargin=dp(6);actions.addView(proof,pp);Button del=button("Delete",false,()->confirmDelete("Delete achievement?",()->{DemoSession.achievements.remove(ix);recreate();}));LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(0,dp(42),1);dp.leftMargin=dp(6);actions.addView(del,dp);c.addView(actions);card(l,c);}action(l,"Add Achievement",()->achievementDialog(-1));}
    void achievementDialog(int index){Achievement old=index>=0?DemoSession.achievements.get(index):null;EditText[] f=new EditText[4];String[] labels={"Achievement Title","Description","Organization","Date"};String[] vals=old==null?new String[]{"","","",""}:new String[]{old.title,old.description,old.organization,old.date};LinearLayout box=column();pad(box,8);for(int i=0;i<f.length;i++){label(box,labels[i]);f[i]=input(labels[i],InputType.TYPE_CLASS_TEXT);f[i].setText(vals[i]);box.addView(f[i],lp(-1,48));}new AlertDialog.Builder(this).setTitle(old==null?"Add Achievement":"Edit Achievement").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{for(EditText e:f)if(e.getText().toString().trim().isEmpty()){e.setError("Required");return;}if(old==null)DemoSession.achievements.add(new Achievement(f[0].getText().toString().trim(),f[1].getText().toString().trim(),f[2].getText().toString().trim(),f[3].getText().toString().trim()));else{old.title=f[0].getText().toString().trim();old.description=f[1].getText().toString().trim();old.organization=f[2].getText().toString().trim();old.date=f[3].getText().toString().trim();}recreate();}).show();}

    void workExperience(){LinearLayout l=page("Work Experience and Internships");note(l,"Add student-entered work or internship history. Entries are stored in this device's demo session.");if(DemoSession.workExperiences.isEmpty())note(l,"No work experience added yet.");for(int i=0;i<DemoSession.workExperiences.size();i++){final int index=i;WorkExperience x=DemoSession.workExperiences.get(i);LinearLayout c=column();pad(c,14);c.addView(text(x.role,17,ink,true));c.addView(text(x.company+" · "+(x.internship?"Internship":"Work experience"),13,blue,true));c.addView(text((x.startDate.isEmpty()?"Date not set":x.startDate+" – "+(x.endDate.isEmpty()?"Present":x.endDate)),13,muted,false));if(!x.description.isEmpty())c.addView(text(x.description,14,muted,false));LinearLayout actions=row();Button edit=button("Edit",false,()->experienceDialog(index));actions.addView(edit,new LinearLayout.LayoutParams(0,dp(44),1));Button delete=button("Delete",false,()->confirmDelete("Delete this experience entry?",()->{DemoSession.workExperiences.remove(index);recreate();}));LinearLayout.LayoutParams delp=new LinearLayout.LayoutParams(0,dp(44),1);delp.leftMargin=dp(6);actions.addView(delete,delp);c.addView(actions);card(l,c);}action(l,"Add Experience or Internship",()->experienceDialog(-1));}
    void experienceDialog(int index){WorkExperience old=index<0?null:DemoSession.workExperiences.get(index);LinearLayout form=column();pad(form,8);EditText company=input("Company name",InputType.TYPE_CLASS_TEXT),role=input("Job role",InputType.TYPE_CLASS_TEXT),start=input("Start date",InputType.TYPE_CLASS_TEXT),end=input("End date or Present",InputType.TYPE_CLASS_TEXT),description=input("Description",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);description.setSingleLine(false);description.setMinLines(3);CheckBox internship=new CheckBox(this);internship.setText("This was an internship");if(old!=null){company.setText(old.company);role.setText(old.role);start.setText(old.startDate);end.setText(old.endDate);description.setText(old.description);internship.setChecked(old.internship);}for(EditText field:new EditText[]{company,role,start,end,description})form.addView(field,lp(-1,field==description?90:48));form.addView(internship);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(old==null?"Add Experience":"Edit Experience").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{if(company.length()==0||role.length()==0){toast("Company and job role are required");return;}WorkExperience updated=new WorkExperience(company.getText().toString().trim(),role.getText().toString().trim(),start.getText().toString().trim(),end.getText().toString().trim(),description.getText().toString().trim(),internship.isChecked());if(old==null)DemoSession.workExperiences.add(updated);else{old.company=updated.company;old.role=updated.role;old.startDate=updated.startDate;old.endDate=updated.endDate;old.description=updated.description;old.internship=updated.internship;}dialog.dismiss();recreate();}));dialog.show();}

    void professionalLinks(){LinearLayout l=page("Professional Links");linkCard(l,"LinkedIn Profile URL","LinkedIn","linkedin.com");linkCard(l,"Personal Portfolio URL","Portfolio","");}
    void linkCard(LinearLayout l,String key,String title,String domain){String url=DemoSession.professionalLinks.getOrDefault(key,"");LinearLayout c=column();pad(c,14);c.addView(text(title,16,ink,true));c.addView(text(url.isEmpty()?"Not provided":url,13,muted,false));LinearLayout r=row();r.addView(button("Edit",false,()->textFieldDialog(title,key,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI,e->{String v=e.getText().toString().trim();if(!v.isEmpty()&&!(domain.isEmpty()?validWebUrl(v):this.domain(v,domain))){e.setError("Enter a valid HTTPS profile URL");return;}DemoSession.professionalLinks.put(key,v);recreate();})),new LinearLayout.LayoutParams(0,dp(44),1));if(!url.isEmpty()){Button open=button("Open",true,()->openUrl(url));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(44),1);p.leftMargin=dp(6);r.addView(open,p);}c.addView(r);card(l,c);}

    void preview(){LinearLayout l=page("Placement Profile Preview");note(l,"Private local preview. Contact details are omitted from this recruiter-style view.");if(!DemoSession.profilePhotoUri.isEmpty()){ImageView photo=new ImageView(this);photo.setImageURI(Uri.parse(DemoSession.profilePhotoUri));photo.setScaleType(ImageView.ScaleType.CENTER_CROP);l.addView(photo,lp(104,104));}heading(l,DemoSession.name);l.addView(text(DemoSession.sapId,13,muted,false));showIf(l,"Programme and branch",value("Programme","" )+"  ·  "+value("Branch",DemoSession.branch));showIf(l,"Academic information","Semester "+value("Current semester","")+"  ·  CGPA "+value("CGPA",""));if(!DemoSession.skills.isEmpty()){heading(l,"Skills");for(Map.Entry<String,LinkedHashSet<String>> e:DemoSession.skills.entrySet())if(!e.getValue().isEmpty())l.addView(text(e.getKey()+": "+joinSkills(e.getValue()),13,muted,false));}if(!DemoSession.workExperiences.isEmpty()){heading(l,"Work experience and internships");for(WorkExperience x:DemoSession.workExperiences)item(l,x.role,x.company+" · "+(x.internship?"Internship":"Work experience")+" · "+x.startDate+" – "+x.endDate,null,null);}if(!DemoSession.projects.isEmpty()){heading(l,"Projects");for(Project p:DemoSession.projects)item(l,p.title,p.githubUrl,"OPEN",()->openUrl(p.githubUrl));}if(!DemoSession.certifications.isEmpty()){heading(l,"Certifications");for(Certification c:DemoSession.certifications)item(l,c.name,c.organization+"  ·  "+c.issueDate,c.fileName.isEmpty()?null:"LOCAL FILE",c.fileUri.isEmpty()?null:()->openLocal(c.fileUri));}boolean coding=false;for(CodingProfile c:DemoSession.codingProfiles.values())if(c.url!=null&&!c.url.isEmpty()){if(!coding){heading(l,"Coding profiles");coding=true;}item(l,c.platform,c.username,c.url,()->openUrl(c.url));}if(!DemoSession.achievements.isEmpty()){heading(l,"Achievements");for(Achievement a:DemoSession.achievements)item(l,a.title,a.organization+"  ·  "+a.date,null,null);}String linkedIn=DemoSession.professionalLinks.get("LinkedIn Profile URL");if(linkedIn!=null&&!linkedIn.isEmpty()){heading(l,"LinkedIn");item(l,"LinkedIn profile",linkedIn,"OPEN",()->openUrl(linkedIn));}String portfolio=DemoSession.professionalLinks.get("Personal Portfolio URL");if(portfolio!=null&&!portfolio.isEmpty()){heading(l,"Portfolio");item(l,"Personal website",portfolio,"OPEN",()->openUrl(portfolio));}String resume=DemoSession.documents.get("Resume/CV");if(resume!=null){heading(l,"Resume");item(l,"Resume/CV",resume,"SELECTED LOCALLY",null);} }
    String joinSkills(LinkedHashSet<String> values){StringBuilder b=new StringBuilder();for(String v:values){if(b.length()>0)b.append(", ");b.append(v);}return b.toString();}
    void showIf(LinearLayout l,String title,String value){if(value!=null&&!value.trim().isEmpty()&&!value.replace("·","").trim().isEmpty())item(l,title,value,null,null);}
}
